{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "CJB 090, which shares the 2,3-dichlorophenylpiperazine core and a similar aryl-linked basic amine motif, entered the brain quickly and showed high brain penetration after IV administration, directly supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904, a close analogue with the same 2,3-dichlorophenylpiperazine and a butyl linker to an aromatic cap, demonstrated high brain penetration after IV dosing, indicating this scaffold is CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "An analogue with the same dichlorophenylpiperazine and a propyl-hydroxy linker to a carbazole amide showed excellent brain penetrability in mice (brain-to-plasma 6-20) after both oral and IV dosing, providing strong evidence for robust CNS exposure in this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A radiolabeled analogue with the same dichlorophenylpiperazine and an amide-linked aromatic group crossed the BBB and localized in rat brain, directly demonstrating CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The closest analogue containing the cyanopyridylpiperazine motif was identified as an efflux transporter substrate in pigs, with brain uptake increased by CsA; this indicates a transporter liability that may reduce exposure but does not by itself preclude meaningful CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Some arylpiperazine 5-HT1A radioligands were P-gp substrates with low brain uptake in rodents, a cautionary signal for transporter-mediated limitation, though these are less structurally similar to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. Multiple close analogues sharing the 2,3-dichlorophenylpiperazine scaffold show high or excellent brain penetration after systemic dosing, and the closest cyanopyridylpiperazine analogue, despite being an efflux substrate, still achieves measurable brain uptake; the transporter liability is not sufficient to predict inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma PK or PET measurement exists for the exact query molecule.",
    "The closest cyanopyridylpiperazine analogue (C13) was studied under efflux inhibition; baseline brain exposure without CsA was not reported.",
    "Species differences in transporter expression and plasma protein binding may affect translation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

